+  <title>Support Contact Form</title>
+  <style>
+    :root {
+      color-scheme: light;
+      --background: #f5f7fb;
+      --surface: #ffffff;
+      --text: #172033;
+      --muted: #5f6b7a;
+      --border: #d8e0eb;
+      --primary: #2563eb;
+      --primary-dark: #1d4ed8;
+      --focus: #93c5fd;
+      --shadow: 0 24px 70px rgba(23, 32, 51, 0.12);
