+        radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 34rem),
+        linear-gradient(135deg, #f8fbff 0%, var(--background) 100%);
+      color: var(--text);
+      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      line-height: 1.5;
+    }
+
+    main {
+      width: min(100%, 560px);
+    }
+
+    .support-card {
+      padding: clamp(28px, 5vw, 44px);
+      border: 1px solid rgba(216, 224, 235, 0.78);
+      border-radius: 28px;
+      background: rgba(255, 255, 255, 0.92);
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(14px);
+    }
+
+    .eyebrow {
+      margin: 0 0 10px;
+      color: var(--primary);
+      font-size: 0.8rem;
+      font-weight: 700;
+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 6vw, 3.2rem);
+      line-height: 1.05;
+      letter-spacing: -0.04em;
+    }
+
+    .intro {
+      margin: 16px 0 30px;
+      color: var(--muted);
+      font-size: 1rem;
+    }
+
+    .form-field {
+      margin-bottom: 20px;
+    }
+
+    label {
+      display: block;
+      margin-bottom: 8px;
+      color: var(--text);
+      font-size: 0.95rem;
+      font-weight: 700;
+    }
+
+    input {
+      width: 100%;
+      min-height: 52px;
+      padding: 13px 15px;
+      border: 1px solid var(--border);
+      border-radius: 14px;
+      background: #ffffff;
+      color: var(--text);
+      font: inherit;
+      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
+    }
+
+    input::placeholder {
+      color: #8b97a8;
+    }
+
+    input:hover {
+      border-color: #b9c5d6;
+    }
+
+    input:focus {
+      border-color: var(--primary);
+      outline: 3px solid var(--focus);
+      outline-offset: 2px;
+      box-shadow: 0 0 0 5px rgba(37, 99, 235, 0.08);
+    }
+
+    .helper-text {
+      margin: 8px 0 0;
+      color: var(--muted);
+      font-size: 0.9rem;
+    }
+
+    button {
+      width: 100%;
+      min-height: 54px;
+      margin-top: 8px;
+      border: 0;
+      border-radius: 16px;
+      background: linear-gradient(135deg, var(--primary), var(--primary-dark));
+      color: #ffffff;
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      letter-spacing: -0.01em;
+      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.3);
+      transition: box-shadow 160ms ease, transform 160ms ease;
+    }
+
+    button:hover {
+      box-shadow: 0 18px 36px rgba(37, 99, 235, 0.36);
+      transform: translateY(-1px);
+    }
+
+    button:focus {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    button:active {
+      transform: translateY(0);
+    }
+
+    .form-status {
+      min-height: 1.5em;
+      margin: 18px 0 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .required-note {
+      margin: 0 0 18px;
+      color: var(--muted);
+      font-size: 0.9rem;
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="support-card" aria-labelledby="support-title">
+      <p class="eyebrow">Support</p>
+      <h1 id="support-title">How can we help?</h1>
+      <p class="intro">Send your contact details and our support team will follow up with you shortly.</p>
+
+      <form id="support-form" novalidate>
+        <p class="required-note">Fields marked with an asterisk are required.</p>
+
+        <div class="form-field">
+          <label for="full-name">Full name *</label>
+          <input
+            type="text"
+            id="full-name"
+            name="fullName"
+            autocomplete="name"
+            placeholder="Jane Doe"
+            required
+          >
+        </div>
+
+        <div class="form-field">
+          <label for="email">Email address *</label>
+          <input
+            type="email"
+            id="email"
+            name="email"
+            autocomplete="email"
+            placeholder="jane@example.com"
+            required
+          >
+        </div>
+
+        <div class="form-field">
+          <label for="phone">Phone number</label>
+          <input
+            type="tel"
+            id="phone"
+            name="phone"
+            autocomplete="tel"
+            inputmode="tel"
+            placeholder="(555) 123-4567"
+            aria-describedby="phone-helper"
+          >
+          <p class="helper-text" id="phone-helper">Use a 10-digit number, such as (555) 123-4567.</p>
+        </div>
+
+        <button type="submit">Contact support</button>
+        <p class="form-status" id="form-status" role="status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#support-form");
+    const statusMessage = document.querySelector("#form-status");
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const formData = new FormData(form);
+      const fullName = String(formData.get("fullName")).trim();
+      const email = String(formData.get("email")).trim();
+
+      if (!fullName || !email) {
+        statusMessage.textContent = "Please provide your full name and email address.";
+        return;
+      }
+
+      const emailField = form.elements.email;
+
+      if (!emailField.validity.valid) {
+        statusMessage.textContent = "Please provide a valid email address.";
+        emailField.focus();
+        return;
+      }
+
+      statusMessage.textContent = "Thanks. Your support request has been prepared.";
+      form.reset();
+    });
+  </script>
+</body>
+</html>
*** End Patch
